#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <psapi.h>
#include <tlhelp32.h>
#include <array>
#include <chrono>
#include <cstdio>
#include <cstdlib>
long long now_ns() {
  return std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::steady_clock::now().time_since_epoch()).count();
}
int main(int argc, char** argv) {
  if (argc != 4) return 2;
  const DWORD pid = strtoul(argv[1], nullptr, 10);
  const auto process = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ | SYNCHRONIZE, FALSE, pid);
  if (!process) return 3;
  DWORD64 base{};
  for (unsigned retry = 0; retry < 1000 && !base; ++retry) {
    const auto snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, pid);
    if (snapshot != INVALID_HANDLE_VALUE) {
      MODULEENTRY32W entry{};
      entry.dwSize = sizeof(entry);
      if (Module32FirstW(snapshot, &entry)) do {
        if (_wcsicmp(entry.szModule, L"gneiss_engine.dll") == 0)
          base = reinterpret_cast<DWORD64>(entry.modBaseAddr);
      } while (Module32NextW(snapshot, &entry));
      CloseHandle(snapshot);
    }
    if (!base) Sleep(1);
  }
  if (!base) return 4;
  FILE* output{};
  if (fopen_s(&output, argv[2], "w") != 0) return 5;
  fprintf(output, "time_ns,rva,valid\n");
  const std::array<DWORD64, 4> rvas{0xceea0, 0xff4e0, 0x545c0, 0xa9950};
  std::array<int, 4> previous{-2,-2,-2,-2};
  std::array<PSAPI_WORKING_SET_EX_INFORMATION, 4> pages{};
  for (unsigned index = 0; index < 4; ++index)
    pages[index].VirtualAddress = reinterpret_cast<void*>(base + rvas[index]);
  const auto timer = CreateWaitableTimerExW(nullptr, nullptr, CREATE_WAITABLE_TIMER_HIGH_RESOLUTION,
                                           TIMER_ALL_ACCESS);
  const bool prefetch = strtoul(argv[3], nullptr, 10) != 0;
  const auto prefetch_at = now_ns() + 180000000000LL;
  bool attempted = false;
  const auto deadline = now_ns() + 1000000000000LL;
  while (WaitForSingleObject(process, 0) == WAIT_TIMEOUT && now_ns() < deadline) {
    if (!attempted && now_ns() >= prefetch_at) {
      attempted = true;
      std::array<WIN32_MEMORY_RANGE_ENTRY, 4> ranges{};
      for (unsigned index = 0; index < 4; ++index) {
        ranges[index].VirtualAddress = reinterpret_cast<void*>((base + rvas[index]) & ~DWORD64{4095});
        ranges[index].NumberOfBytes = 4096;
      }
      const auto started = now_ns();
      SetLastError(0);
      const bool ok = !prefetch || PrefetchVirtualMemory(process, ranges.size(), ranges.data(), 0);
      const auto error = GetLastError();
      const auto ended = now_ns();
      fprintf(stderr, "prefetch=%d start_ns=%lld end_ns=%lld success=%d error=%lu bytes=%u\n",
              prefetch, started, ended, ok, error, prefetch ? 16384U : 0U);
      fflush(stderr);
    }
    const bool queried = QueryWorkingSetEx(process, pages.data(), sizeof(pages));
    const auto stamp = now_ns();
    for (unsigned index = 0; index < 4; ++index) {
      const int valid = queried ? static_cast<int>(pages[index].VirtualAttributes.Valid) : -1;
      if (valid != previous[index]) {
        fprintf(output, "%lld,%llx,%d\n", stamp, rvas[index], valid);
        fflush(output);
        previous[index] = valid;
      }
    }
    if (timer) {
      LARGE_INTEGER due{};
      due.QuadPart = -10000;
      SetWaitableTimerEx(timer, &due, 0, nullptr, nullptr, nullptr, 0);
      WaitForSingleObject(timer, 100);
    } else Sleep(1);
  }
  if (timer) CloseHandle(timer);
  fclose(output);
  CloseHandle(process);
  return 0;
}

